'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const { createParser, parse } = require('./src/csv');
const { toObjects } = require('./src/rows');

const quote = '"';
const cases = [
  ['', []],
  ['\uFEFF', []],
  ['\n', [['']]],
  ['\r\n\r\n', [[''], ['']]],
  ['a\rb\r\nc\nd', [['a'], ['b'], ['c'], ['d']]],
  ['a\r\n', [['a']]],
  [',,', [['', '', '']]],
  ['""', [['']]],
  ['""""', [[quote]]],
  ['"a,b","say ""hi"""\n', [['a,b', 'say "hi"']]],
  ['"a\r\nb\rc\nd",tail\r\n', [['a\r\nb\rc\nd', 'tail']]],
  ['a"b,c"d\n', [['a"b', 'c"d']]],
  ['\uFEFFa,\uFEFFb\n\uFEFFc', [['a', '\uFEFFb'], ['\uFEFFc']]],
  ['😀,"😀"', [['😀', '😀']]],
];

test('grammar is independent of every pair of chunk boundaries', () => {
  for (const [text, expected] of cases) {
    assert.deepEqual(parse(text), expected);
    for (let first = 0; first <= text.length; first++) {
      for (let second = first; second <= text.length; second++) {
        const parser = createParser();
        const actual = [];
        for (const chunk of [text.slice(0, first), '', text.slice(first, second), '', text.slice(second)]) {
